function validate([timeSeries, duration]) {
  if (timeSeries.length < 1 || timeSeries.length > 10000) return 'timeSeries needs 1 to 10^4 attack times.';
  if (timeSeries.some(t => !Number.isInteger(t) || t < 0 || t > 1e7)) return 'Each attack time is an integer from 0 to 10^7.';
  if (!Number.isInteger(duration) || duration < 0 || duration > 1e7) return 'duration is an integer from 0 to 10^7.';
  for (let i = 1; i < timeSeries.length; i++) if (timeSeries[i] < timeSeries[i - 1]) return 'timeSeries must be sorted in non-decreasing order.';
  return null;
}

