function findPoisonedDuration(timeSeries, duration) {
  let total = 0;
  let poisonedUntil = 0;
  for (const time of timeSeries) {
    const end = time + duration;
    const start = Math.max(time, poisonedUntil);
    total += end - start;
    poisonedUntil = end;
  }
  return total;
}

