function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const times = Array.from({ length: n }, () => Math.floor(rand() * 10000001)).sort((a, b) => a - b);
    const duration = Math.floor(rand() * 20001);
    return [times, duration];
  }
  const n = 1 + Math.floor(rand() * 7);
  const times = Array.from({ length: n }, () => Math.floor(rand() * 16)).sort((a, b) => a - b);
  const duration = Math.floor(rand() * 6);
  return [times, duration];
}
